import { createHash } from 'node:crypto';
import { scanSecrets } from '../security/secret-patterns.js';

/**
 * The rules Studio keeps for a project, as files in its repository (plan T, T4): skills, lessons learned, playbooks and
 * the default acceptance criteria under `.nb-studio/harness/`, and one rule file for agents that read `.agents/rules/`.
 * Nothing is written to `.agents/skills/`: that folder is generated by the framework (Q4). Pure, so it is tested without
 * a repository.
 */

export const HARNESS_DIR = '.nb-studio/harness';
export const HARNESS_RULE_PATH = '.agents/rules/ds-harness.md';
export const MANIFEST_PATH = `${HARNESS_DIR}/manifest.json`;

export interface HarnessInput {
  readonly projectName: string;
  readonly skills: readonly {
    readonly slug: string;
    readonly name: string;
    readonly content: string;
  }[];
  readonly lessons: readonly {
    readonly rule: string;
    readonly mistake: string;
    readonly tag: string;
  }[];
  readonly playbooks: readonly {
    readonly slug: string;
    readonly name: string;
    readonly description: string;
    readonly instructions: string;
  }[];
  readonly criteria: readonly {
    readonly text: string;
    readonly checkKind: string;
    readonly checkValue: string | null;
  }[];
}

export interface HarnessFile {
  readonly path: string;
  readonly content: string;
}

const sha256 = (value: string): string =>
  createHash('sha256').update(value).digest('hex');

const HEADER =
  /^<!-- generated-by: duongsinh-studio · revision: (\S+) · hash: ([0-9a-f]{64}) -->\n\n/u;

/** A markdown body with the header that says where it came from and what it was when written. */
function marked(body: string, revision: string): string {
  return `<!-- generated-by: duongsinh-studio · revision: ${revision} · hash: ${sha256(body)} -->\n\n${body}`;
}

const safeSlug = (slug: string): string =>
  slug
    .toLowerCase()
    .replace(/[^a-z0-9-_]+/gu, '-')
    .replace(/^-+|-+$/gu, '') || 'item';

function bodies(input: HarnessInput): { path: string; body: string }[] {
  const out: { path: string; body: string }[] = [];
  for (const skill of [...input.skills].sort((a, b) =>
    a.slug.localeCompare(b.slug),
  ))
    out.push({
      path: `${HARNESS_DIR}/skills/${safeSlug(skill.slug)}/SKILL.md`,
      body: `${skill.content.trim()}\n`,
    });
  out.push({
    path: `${HARNESS_DIR}/lessons.md`,
    body:
      [
        `# Bài học của ${input.projectName}`,
        '',
        ...(input.lessons.length === 0
          ? ['Chưa có bài học nào được duyệt.']
          : input.lessons.flatMap((lesson) => [
              `## ${lesson.tag}`,
              '',
              `- **Quy tắc**: ${lesson.rule}`,
              `- **Lỗi đã gặp**: ${lesson.mistake}`,
              '',
            ])),
      ].join('\n') + '\n',
  });
  for (const playbook of [...input.playbooks].sort((a, b) =>
    a.slug.localeCompare(b.slug),
  ))
    out.push({
      path: `${HARNESS_DIR}/playbooks/${safeSlug(playbook.slug)}.md`,
      body: `# ${playbook.name} (\`!${playbook.slug}\`)\n\n${playbook.description}\n\n${playbook.instructions.trim()}\n`,
    });
  out.push({
    path: `${HARNESS_DIR}/criteria-template.md`,
    body:
      [
        `# Tiêu chí nghiệm thu mặc định của ${input.projectName}`,
        '',
        ...(input.criteria.length === 0
          ? ['Chưa đặt tiêu chí mặc định.']
          : input.criteria.map(
              (c) =>
                `- [${c.checkKind}] ${c.text}${c.checkValue ? ` — \`${c.checkValue}\`` : ''}`,
            )),
      ].join('\n') + '\n',
  });
  out.push({
    path: HARNESS_RULE_PATH,
    body:
      [
        '# Bộ quy tắc của Dương Sinh Studio',
        '',
        `Các tệp trong \`${HARNESS_DIR}/\` do Dương Sinh Studio ghi từ những gì dự án đã chốt (kỹ năng, bài học, playbook, tiêu chí).`,
        'Đọc chúng trước khi làm. Đừng sửa tay: sửa trong Studio rồi xuất lại; sửa tay sẽ bị báo là lệch.',
        '',
        `- \`${HARNESS_DIR}/skills/<tên>/SKILL.md\`: cách làm theo từng chủ đề.`,
        `- \`${HARNESS_DIR}/lessons.md\`: lỗi đã gặp và quy tắc rút ra.`,
        `- \`${HARNESS_DIR}/playbooks/\`: các việc lặp lại và cách làm chuẩn.`,
        `- \`${HARNESS_DIR}/criteria-template.md\`: tiêu chí nghiệm thu mặc định.`,
      ].join('\n') + '\n',
  });
  return out;
}

/** Every file Studio would write for `input`, headers and manifest included; the same input gives the same files. */
export function buildHarnessFiles(input: HarnessInput): HarnessFile[] {
  const parts = bodies(input);
  const revision = sha256(
    parts.map((p) => `${p.path}\n${sha256(p.body)}`).join('\n'),
  ).slice(0, 12);
  const files = parts.map((part) => ({
    path: part.path,
    content: marked(part.body, revision),
  }));
  const manifest = {
    generatedBy: 'duongsinh-studio',
    revision,
    files: Object.fromEntries(parts.map((p) => [p.path, sha256(p.body)])),
  };
  return [
    ...files,
    { path: MANIFEST_PATH, content: `${JSON.stringify(manifest, null, 2)}\n` },
  ];
}

/** What looks like a secret in the files: how many, and in which files, never the text. */
export function scanHarnessFiles(files: readonly HarnessFile[]): {
  count: number;
  paths: string[];
} {
  let count = 0;
  const paths: string[] = [];
  for (const file of files) {
    const found = scanSecrets(file.content).length;
    if (found > 0) {
      count += found;
      paths.push(file.path);
    }
  }
  return { count, paths };
}

const INDEX_ROW =
  '| [.agents/rules/ds-harness.md](.agents/rules/ds-harness.md) | Trước khi làm việc: kỹ năng, bài học và playbook mà Dương Sinh Studio ghi cho dự án |';

/** `AGENTS.md` with one more row in its Index table, or null when it has none or already has the row. */
export function addIndexRow(agentsMd: string): string | null {
  if (agentsMd.includes('.agents/rules/ds-harness.md')) return null;
  const lines = agentsMd.split('\n');
  const heading = lines.findIndex((line) => /^##\s+Index\b/u.test(line));
  if (heading < 0) return null;
  let last = -1;
  for (let i = heading + 1; i < lines.length; i += 1) {
    if (lines[i]?.trim().startsWith('|')) last = i;
    else if (last >= 0) break;
  }
  if (last < 0) return null;
  lines.splice(last + 1, 0, INDEX_ROW);
  return lines.join('\n');
}

/** How the repository's copy differs from what Studio would write now. */
export function driftOf(
  files: readonly HarnessFile[],
  repository: ReadonlyMap<string, string>,
): { missing: string[]; edited: string[]; outdated: boolean } {
  const missing: string[] = [];
  const edited: string[] = [];
  let outdated = false;
  for (const file of files) {
    const present = repository.get(file.path);
    if (present === undefined) {
      missing.push(file.path);
      continue;
    }
    if (present === file.content) continue;
    const written = HEADER.exec(present);
    const body = written ? present.slice(written[0].length) : present;
    // A body that no longer matches the hash in its own header was edited by hand; a body that matches it but differs
    // from what Studio would write now is only out of date.
    if (written && sha256(body) !== written[2]) edited.push(file.path);
    else outdated = true;
  }
  return { missing, edited, outdated };
}
